package com.aoo.bcg.wordcard;
import com.aoo.bcg.gamespi.*;import com.aoo.bcg.gamespi.time.*;import java.util.*;
final class AhphzSession implements AuthoritativeGameSession{
 private final long room,owner;private final RulePayload raw;private final AhphzRules.Config cfg;private final Map<Integer,Long>players=new LinkedHashMap<>();private final Set<Integer>ready=new LinkedHashSet<>(),guChou=new LinkedHashSet<>();private final Map<Integer,Integer>piao=new LinkedHashMap<>();private final Map<Integer,Set<Integer>>passedChi=new LinkedHashMap<>();private final List<Object>events=new ArrayList<>();private final OperationDeadlineArbiter arbiter=new OperationDeadlineArbiter();private WordCardState game;private long sequence,version;
 AhphzSession(long room,long owner,RulePayload rules){if(room<=0||owner<=0)throw new IllegalArgumentException("invalid AHPHZ room");this.room=room;this.owner=owner;raw=rules==null?RulePayload.empty():rules;cfg=parse(raw.asMap());players.put(0,owner);piao.put(0,fixedPiao());passedChi.put(0,new LinkedHashSet<>());}
 public synchronized GameCommandResult execute(GameCommandRequest r){if(r.roomId()!=room||r.sequence()<=sequence)throw new IllegalArgumentException("invalid AHPHZ command order");long id=id(r.authenticatedUserId());String a=String.valueOf(r.body().asMap().getOrDefault("action","state"));boolean changed=true;switch(a){case"state","CAHPHZGetRoomInfo"->{participant(id);changed=false;}case"join","CAHPHZEnterRoom"->join(r.seatId(),id);case"ready","CAHPHZReadyRoom"->{own(r.seatId(),id);waiting();ready.add(r.seatId());}case"piao","CAHPHZPiaoHua"->{own(r.seatId(),id);waiting();int n=num(r.body().asMap().getOrDefault("piao",0));if(n<0||n>4)throw new IllegalArgumentException("invalid piao");piao.put(r.seatId(),n);}case"guChou","CAHPHZGuChou"->{own(r.seatId(),id);if(!cfg.guChou())throw new IllegalStateException("gu-chou disabled");guChou.add(r.seatId());}case"start","CAHPHZStartGame"->start(id);case"operation","CAHPHZOpCard"->operate(r,id);default->throw new IllegalArgumentException("unsupported AHPHZ action");}sequence=r.sequence();if(changed){version++;events.add(Map.of("version",version,"after",snapshot()));}return new GameCommandResult("wordcard.ahphz.response",r.requestId(),viewFor(id));}
 private void join(int seat,long id){waiting();if(seat<0||seat>=cfg.playerCount()||players.putIfAbsent(seat,id)!=null)throw new IllegalStateException("invalid/occupied AHPHZ seat");piao.put(seat,fixedPiao());passedChi.put(seat,new LinkedHashSet<>());}
 private void start(long id){if(id!=owner)throw new SecurityException("owner only");waiting();if(players.size()!=cfg.playerCount()||!ready.containsAll(players.keySet().stream().filter(x->x!=0).toList()))throw new IllegalStateException("players not ready");List<Integer>d=new ArrayList<>(AhphzRules.deck());Collections.shuffle(d,new Random(room));Map<Integer,List<Integer>>h=new LinkedHashMap<>();Map<Integer,Integer>x=new LinkedHashMap<>();for(int seat:players.keySet()){int count=seat==0?21:20;List<Integer>hand=new ArrayList<>();for(int i=0;i<count;i++)hand.add(d.removeFirst());h.put(seat,hand);x.put(seat,0);}for(int i=0;i<cfg.drawRemoval();i++)d.removeLast();game=new WordCardState(h,d,List.of(),x,0,WordCardPhase.PLAYING,null,null);}
 private void operate(GameCommandRequest r,long id){own(r.seatId(),id);if(game==null)throw new IllegalStateException("round not started");Map<String,Object>b=map(r.body().asMap().getOrDefault("payload",Map.of()));WordCardOperation op=WordCardOperation.valueOf(String.valueOf(b.getOrDefault("operation","PASS")));List<Integer>cards=b.get("cards")instanceof Collection<?>c?c.stream().map(AhphzSession::num).toList():List.of();if(guChou.contains(r.seatId())&&op!=WordCardOperation.PASS)throw new IllegalStateException("gu-chou player cannot operate");if(op==WordCardOperation.CHI&&!AhphzRules.legalChi(game.hands().get(r.seatId()),game.exposedCard(),passedChi.get(r.seatId()),cfg.oppositeCannotChi(),opposite(r.seatId(),game.currentSeat())))throw new IllegalStateException("chi prohibited");if(op==WordCardOperation.PASS&&game.exposedCard()!=null&&AhphzRules.legalChi(game.hands().get(r.seatId()),game.exposedCard(),Set.of(),false,false))passedChi.get(r.seatId()).add(AhphzRules.type(game.exposedCard()));int xi=num(b.getOrDefault("huXi",game.huXi().get(r.seatId())));boolean can=AhphzRules.canHu(game.hands().get(r.seatId()),xi);game=new WordCardCoreEngine<>(new AhphzRuleSet()).apply(game,new WordCardCommand(op,r.seatId(),cards),new AhphzRuleSet.Context(cfg,xi,can,passedChi.get(r.seatId()),false));}
 private boolean opposite(int a,int b){return players.size()==2&&a!=b;}
 public synchronized Map<String,Object>viewFor(long viewer){Integer mine=seat(viewer);Map<Integer,Object>s=new LinkedHashMap<>();players.forEach((pos,id)->{List<Integer>h=game==null?List.of():game.hands().get(pos);s.put(pos,Map.of("playerId",id,"ready",ready.contains(pos),"piao",piao.get(pos),"guChou",guChou.contains(pos),"cards",Objects.equals(pos,mine)||game!=null&&game.phase()==WordCardPhase.FINISHED?h:Collections.nCopies(h.size(),0),"cardCount",h.size(),"huXi",game==null?0:game.huXi().get(pos)));});return Map.of("roomId",room,"gameCode","ahphz","started",game!=null,"phase",game==null?"WAITING":game.phase().name(),"currentSeat",game==null?-1:game.currentSeat(),"winnerSeat",game==null||game.winnerSeat()==null?-1:game.winnerSeat(),"seats",Map.copyOf(s),"stateVersion",version);}
 public synchronized Map<String,Object>authoritativeState(){return snapshot();}public synchronized long stateVersion(){return version;}synchronized List<Object>events(){return List.copyOf(events);}private Map<String,Object>snapshot(){Map<String,Object>s=new LinkedHashMap<>();s.put("schemaVersion",1);s.put("roomId",room);s.put("ownerId",owner);s.put("players",Map.copyOf(players));s.put("ready",List.copyOf(ready));s.put("piao",Map.copyOf(piao));s.put("guChou",List.copyOf(guChou));s.put("passedChi",passedChi);s.put("rules",raw.asMap());s.put("sequence",sequence);s.put("stateVersion",version);s.put("game",game==null?"WAITING":encode(game));return Map.copyOf(s);}
 static AhphzSession restore(Map<String,Object>s){if(num(s.get("schemaVersion"))!=1)throw new IllegalArgumentException("bad AHPHZ schema");AhphzSession x=new AhphzSession(lng(s.get("roomId")),lng(s.get("ownerId")),RulePayload.copyOf(map(s.get("rules"))));x.players.clear();map(s.get("players")).forEach((k,v)->x.players.put(Integer.parseInt(k),lng(v)));x.ready.addAll(ints(s.get("ready")));x.piao.clear();map(s.get("piao")).forEach((k,v)->x.piao.put(Integer.parseInt(k),num(v)));x.guChou.addAll(ints(s.get("guChou")));x.passedChi.clear();map(s.get("passedChi")).forEach((k,v)->x.passedChi.put(Integer.parseInt(k),new LinkedHashSet<>(ints(v))));if(s.get("game")instanceof Map<?,?>)x.game=decode(map(s.get("game")));x.sequence=lng(s.get("sequence"));x.version=lng(s.get("stateVersion"));return x;}
 static StatePayload replay(StatePayload base,List<Object>events){Map<String,Object>s=new LinkedHashMap<>(base.asMap());long v=lng(s.get("stateVersion"));for(Object raw:events){Map<String,Object>e=map(raw);if(lng(e.get("version"))!=++v)throw new IllegalArgumentException("AHPHZ replay gap");s=new LinkedHashMap<>(map(e.get("after")));}return StatePayload.copyOf(s);}
 private static Map<String,Object>encode(WordCardState s){return Map.of("hands",s.hands(),"deck",s.deck(),"discards",s.discards(),"huXi",s.huXi(),"currentSeat",s.currentSeat(),"phase",s.phase().name(),"exposed",s.exposedCard()==null?-1:s.exposedCard(),"winner",s.winnerSeat()==null?-1:s.winnerSeat());}private static WordCardState decode(Map<String,Object>m){Map<Integer,List<Integer>>h=new LinkedHashMap<>();map(m.get("hands")).forEach((k,v)->h.put(Integer.parseInt(k),ints(v)));Map<Integer,Integer>x=new LinkedHashMap<>();map(m.get("huXi")).forEach((k,v)->x.put(Integer.parseInt(k),num(v)));int e=num(m.get("exposed")),w=num(m.get("winner"));return new WordCardState(h,ints(m.get("deck")),ints(m.get("discards")),x,num(m.get("currentSeat")),WordCardPhase.valueOf(String.valueOf(m.get("phase"))),e<0?null:e,w<0?null:w);}
 public OperationDeadline operationDeadline(){return OperationDeadline.none();}public OperationDeadlineArbiter deadlineArbiter(){return arbiter;}public synchronized List<String>invariantViolations(){List<String>v=new ArrayList<>();if(!players.containsValue(owner))v.add("OWNER_NOT_SEATED");if(game!=null){int cards=game.deck().size()+game.discards().size()+game.hands().values().stream().mapToInt(List::size).sum()+cfg.drawRemoval();if(cards>80)v.add("CARD_CONSERVATION");}return v;}public synchronized SettlementPayload settlement(int round,String pv){if(game==null||game.phase()!=WordCardPhase.FINISHED)throw new IllegalStateException("round not finished");int w=game.winnerSeat();long unit=AhphzRules.winnerScore(game.huXi().get(w),AhphzRules.colorWin(game.hands().get(w)),cfg.charge(),piao.get(w),0);Map<Long,Long>d=new LinkedHashMap<>();long gain=0;for(var e:players.entrySet())if(e.getKey()!=w){long loss=unit+piao.get(e.getKey());d.put(e.getValue(),-loss);gain+=loss;}d.put(players.get(w),gain);return new SettlementPayload(room,round,pv,d);}
 private int fixedPiao(){return cfg.charge();}private void waiting(){if(game!=null)throw new IllegalStateException("round started");}private void own(int s,long id){if(!Long.valueOf(id).equals(players.get(s)))throw new SecurityException("seat not owned");}private void participant(long id){if(!players.containsValue(id))throw new SecurityException("not participant");}private Integer seat(long id){return players.entrySet().stream().filter(e->e.getValue()==id).map(Map.Entry::getKey).findFirst().orElse(null);}private static AhphzRules.Config parse(Map<String,Object>r){return new AhphzRules.Config(num(r.getOrDefault("playerCount",2)),num(r.getOrDefault("drawRemoval",0)),num(r.getOrDefault("charge",0)),bool(r,"selfDrawMandatory"),bool(r,"oppositeCannotChi"),bool(r,"guChou"),bool(r,"scoreFloorZero"));}private static boolean bool(Map<String,Object>m,String k){return Boolean.TRUE.equals(m.get(k));}private static int num(Object v){return v instanceof Number n?n.intValue():Integer.parseInt(String.valueOf(v));}private static long lng(Object v){return v instanceof Number n?n.longValue():Long.parseLong(String.valueOf(v));}private static long id(String v){long x=Long.parseLong(v);if(x<=0)throw new IllegalArgumentException("bad player");return x;}private static List<Integer>ints(Object v){return((Collection<?>)v).stream().map(AhphzSession::num).toList();}@SuppressWarnings("unchecked")private static Map<String,Object>map(Object v){Map<String,Object>x=new LinkedHashMap<>();((Map<?,?>)v).forEach((k,n)->x.put(String.valueOf(k),n));return x;}
}
